BEGIN;

-- 2026年版 Professional Cloud DevOps Engineer 試験ガイドで新たに明記された
-- AI関連の出題項目（Gemini Code/Cloud Assist、Gemini CLI、MLワークロードのCI/CD、Active Assist）を
-- 既存の gcp-pcde セットに追加する。

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('gcp-pcde-q41', '組織のブートストラップと維持',
   '開発チームが Cloud Workstations 上に開発環境を用意する際、GoogleのAI支援ツールの役割分担について整理したい。正しい組み合わせはどれか。',
   NULL::text,
   '["Gemini Code AssistはIDE内でのコード補完・生成を、Gemini Cloud AssistはConsole上でのアーキテクチャ提案や運用相談を、Gemini CLIはターミナルでの自然言語操作・自動化を担う。","Gemini Code AssistはConsole上の運用相談を、Gemini Cloud AssistはIDE内のコード補完を、Gemini CLIはCI/CDパイプラインの実行エンジンそのものを担う。","Gemini Code Assist・Gemini Cloud Assist・Gemini CLIはいずれも同一の窓口であり、利用場所が違うだけで担う役割に差は無い。","Gemini Code AssistとGemini CLIはIDEの拡張機能として統合されており、Gemini Cloud Assistはサードパーティ監視ツール専用の連携機能である。"]',
   0,
   '[0]',
   'single',
   '{"asked":"開発環境まわりのAI支援ツール（Gemini Code Assist / Cloud Assist / CLI）の役割分担を理解しているか。","why_asked":"Googleは開発と運用の両方にGeminiを組み込む方向に舵を切った。試験は名前が似た3つのツールを『どれも同じAIだから』とひとくくりにする油断を突き、利用面（IDE/Console/ターミナル)で役割が分かれていることを見ているかを測る。","kid":"コードを書く時はCode Assist、クラウドの相談はCloud Assist、ターミナル作業はCLI、と場所で役割が分かれている。","terms":[["Gemini Code Assist","IDE内でコード補完・生成を支援するAIアシスタント。"],["Gemini Cloud Assist","Google Cloud Console上でアーキテクチャ提案やトラブル対応を支援するAIアシスタント。"],["Gemini CLI","ターミナルから自然言語でGoogle Cloudの操作を自動化するAIエージェント。"]],"think":"『どこで作業しているか』を軸に考える。エディタの中ならCode Assist、コンソールでの設計相談ならCloud Assist、ターミナルでの自動化ならCLI、と使う場面がそのままツール名に対応している。","vs":"3つとも同じGeminiモデルを使うが、統合される場所（IDE/Console/ターミナル)が違うため役割も違う。『同じAIだから同じ』という発想が誤答へ誘導される。","opt":["正解。IDE・Console・ターミナルという利用面の違いがそのまま役割の違いになっている。","Code AssistとCloud Assistの役割が入れ替わっている上、CLIをパイプラインの実行エンジンと誤って説明している。","利用場所が違うのに役割に差が無いとするのは、3つのツールが別々に用意されている理由を無視している。","Cloud AssistをGoogle純正ではなくサードパーティ連携専用と誤って説明している。"]}'),

  ('gcp-pcde-q42', 'CI/CDパイプラインの構築と実装',
   'アプリケーションと同じCI/CDパイプラインの型を機械学習モデルのデプロイにも流用しようとしている。機械学習ワークロード特有の観点として追加すべきものはどれか。',
   NULL::text,
   '["コードの単体テストに加えて、モデルの精度やデータドリフトなどモデル品質の指標を評価ステージに組み込み、基準を満たさなければデプロイをゲートする。","モデルはコードと違って壊れても影響が小さいため、単体テストとリンティングだけを通れば十分とする。","モデルの学習には時間がかかるため、CI/CDのステージはすべて省略し、手動でモデルファイルを本番へ配置する運用にする。","アプリケーションのデプロイと完全に同一の成功指標（レイテンシとエラー率のみ）で、モデルのロールアウト可否を判断する。"]',
   0,
   '[0]',
   'single',
   '{"asked":"MLワークロード特有のCI/CDパイプライン設計（品質ゲートの違い）を理解しているか。","why_asked":"試験ガイドはCI/CDの対象に機械学習ワークロードを明記し、成功指標もアプリケーションまたはMLパイプラインのテレメトリと並記している。試験はアプリのCI/CDをそのまま流用し、モデル固有の品質劣化（精度低下・データドリフト）を検知しないままデプロイし続ける失敗を突く。","kid":"コードのテストだけでなく、モデルの『賢さ』が落ちていないかもゲートでチェックする。","terms":[["データドリフト","本番データの分布が学習時と乖離し、モデルの精度が実運用で劣化する現象。"],["品質ゲート","基準を満たさない成果物をパイプラインの途中で止める仕組み。"]],"think":"アプリのバグはコードのテストで検知できるが、モデルの劣化はコード上は正常でも起きる。だからコードのテストとは別に、モデル自身の出力品質を測る指標をゲートに加える必要がある。","vs":"『壊れても影響が小さいから省略してよい』『時間がかかるから手動で十分』という省略の発想が誤答。モデル固有の劣化はコードのテストでは拾えないため、省略するほど検知が遅れる。","opt":["正解。コードのテストとは別に、モデル品質の指標を評価ステージとして組み込むのがML特有の追加観点。","モデルの劣化はコード上のバグと違い、ビジネスへの影響が地味に大きい。単体テストとリンティングだけでは精度低下を検知できない。","ステージを省略した手動配置は再現性も監査性も失い、CI/CDを導入する意味そのものを打ち消す。","レイテンシとエラー率だけではモデルの精度低下やドリフトを検知できず、劣化したモデルを出し続けてしまう。"]}'),

  ('gcp-pcde-q43', 'オブザーバビリティの実践',
   '大量のログから障害の根本原因を特定する作業に時間がかかっている。Gemini Cloud Assistのログ分析支援を使う場合、最も適切な使い方はどれか。',
   NULL::text,
   '["Logs Explorer上で自然言語により「このエラーの主な原因は何か」のように問いかけ、関連ログの要約や原因の仮説をAIに出させた上で、人が裏付けを取って判断する。","AIの要約結果をそのまま障害報告書の結論として採用し、人によるログの裏付け確認は省略する。","Gemini Cloud Assistはログの保存先を自動でBigQueryへ切り替える機能であり、ログの内容解釈には関与しない。","自然言語での問いかけには対応していないため、Logging クエリ言語を正確に書けることが前提になる。"]',
   0,
   '[0]',
   'single',
   '{"asked":"Gemini Cloud Assistによるログ分析支援の役割と使いどころを理解しているか。","why_asked":"試験ガイドはログの分析・管理の項目にAIによるログ分析支援を明記した。試験はAIの要約を鵜呑みにして裏付けを省く運用と、逆にAI支援の存在自体を過小評価する運用の両方を誤答として置き、『AIは仮説出し、判断は人』という役割分担を測る。","kid":"AIに自然な言葉で聞いて仮説を出してもらい、最終確認は自分でする。","terms":[["Logs Explorer","Cloud Loggingでログを検索・分析するコンソール画面。"],["Gemini Cloud Assist","Console上で自然言語による質問に答えるAI支援機能。"]],"think":"AIは大量のログを高速に要約し仮説を出すのが得意だが、本番判断の責任は人にある。仮説出しをAIに任せ、裏付けと最終判断は人が担う、という役割分担で考える。","vs":"AIの結論をそのまま採用するか、AI支援自体を無視するかのどちらかに寄ると誤る。『仮説はAI、裏付けは人』という中間の使い方が正しい。","opt":["正解。自然言語で問いかけて仮説を得て、人が裏付けを取るのがGemini Cloud Assistの想定用途。","AIの要約はあくまで仮説であり、裏付けなしに結論として採用すると誤った原因特定を報告するリスクがある。","Gemini Cloud Assistはログの保存先切り替え機能ではなく、ログ内容の解釈・要約を支援する機能である。","Gemini Cloud Assistは自然言語での問いかけに対応しており、Logging クエリ言語の習熟を前提としない使い方ができる。"]}'),

  ('gcp-pcde-q44', 'オブザーバビリティの実践',
   'Metrics Explorerでダッシュボードを見ても、あるサービスのレイテンシが悪化した要因の見当がつかない。Gemini Cloud Assistをこの場面でどう使うのが適切か。',
   NULL::text,
   '["表示されているメトリクスについて自然言語で「悪化の要因として考えられるものは何か」と尋ね、関連するメトリクスやリソースの変化を手がかりとして提示させ、原因調査の起点にする。","メトリクスの解釈はAIの担当外であり、アラートポリシーの閾値設定のみに機能が限定されている。","AIに聞く前にまずSLOを再定義し直し、レイテンシの悪化自体を許容範囲に含めてしまう。","AIの提示した要因候補をそのまま原因として確定し、対応チケットの原因欄に記載する。"]',
   0,
   '[0]',
   'single',
   '{"asked":"Gemini Cloud Assistによるメトリクス解釈支援の位置づけを理解しているか。","why_asked":"試験ガイドはメトリクス・ダッシュボード・アラートの管理項目にAIによるメトリクス解釈支援を明記した。試験はメトリクスの意味づけという地味な作業をAIがどこまで肩代わりするかの線引きを問い、『手がかりの提示』と『原因の確定』を混同させる誤答を置く。","kid":"AIに『何が原因っぽいか』のヒントをもらい、そこから人が調査を始める。","terms":[["Metrics Explorer","メトリクスをグラフとして可視化・分析するコンソール画面。"],["SLO","サービスレベル目標。守るべき品質の基準線。"]],"think":"AIはメトリクス間の相関やリソースの変化点を素早く洗い出せるが、因果関係の確定には調査が要る。ヒントを得て調査を始める起点としてAIを使う、という位置づけで考える。","vs":"『AIは無関係』と過小評価する誤答と、『AIの候補=確定原因』と過信する誤答の両方が置かれている。ヒントとして使い、確定は調査後、が正しい線。","opt":["正解。自然言語で要因の手がかりを尋ね、そこから調査を始めるのがGemini Cloud Assistの使い方。","Gemini Cloud Assistはアラート閾値設定に限定された機能ではなく、メトリクスの解釈も支援する。","悪化の原因を調べる前にSLOの基準そのものを緩めるのは、問題を測定から見えなくするだけで解決していない。","AIが提示するのはあくまで候補であり、裏付けなしに確定原因として記載すると誤った対応につながる。"]}'),

  ('gcp-pcde-q45', 'オブザーバビリティの実践',
   '分散トレーシングでリクエストのどこに遅延が集中しているか特定したいが、スパンの数が多く追いきれない。Gemini Cloud Assistのトレース分析支援をどう活用するのが適切か。',
   NULL::text,
   '["トレースのウォーターフォールについて自然言語で「どのスパンが遅延の主要因か」と尋ね、注目すべきスパンを絞り込んだ上で、該当スパンのログやコードを人が詳しく調べる。","トレース分析支援はOpenTelemetryを導入していない環境でのみ使え、既存のトレーシング基盤とは併用できない。","スパンが多すぎる場合はトレース収集自体を停止し、メトリクスとログだけで遅延原因を判断する。","AIが絞り込んだスパンを見た時点で調査を打ち切り、そのスパンの担当チームに修正を依頼する。"]',
   0,
   '[0]',
   'single',
   '{"asked":"Gemini Cloud Assistによるトレース分析支援の位置づけを理解しているか。","why_asked":"試験ガイドは分散トレースの収集・分析の項目にAIによるトレース分析支援を明記した。試験は大量のスパンを前にした絞り込み作業をAIがどこまで担うかを問い、『絞り込みの支援』と『調査の代替』を混同させる誤答を置く。","kid":"AIに『どのスパンが遅いか』を絞り込んでもらい、そこから先を人が詳しく調べる。","terms":[["ウォーターフォール","トレースの各スパンを時系列に並べた表示形式。処理の流れと所要時間が視覚的にわかる。"],["スパン","トレース内の1つの処理区間を表す単位。"]],"think":"スパンの数が多いほど人力での目視は時間がかかる。AIに絞り込みだけを任せ、絞り込んだ後の詳細調査は人が担う、という分業で考える。","vs":"『既存基盤と併用できない』『収集自体をやめる』は機能の存在を無視した誤答、『AIの絞り込みで調査終了』は代替と支援を取り違えた誤答。","opt":["正解。自然言語で主要因スパンを尋ねて絞り込み、そこから先は人が詳細を調べるのが適切な使い方。","Gemini Cloud Assistは既存のOpenTelemetryベースのトレーシング基盤と併用でき、導入有無を問わない機能ではない。","スパンが多いことを理由に収集自体を止めると、遅延箇所を特定する手がかりそのものを失う。","AIによる絞り込みは調査の起点であり、絞り込んだスパンを見ただけで原因を確定するのは早計。"]}'),

  ('gcp-pcde-q46', 'パフォーマンス最適化とトラブルシューティング',
   'コストとパフォーマンスの両面で改善余地がないか、手動で全リソースを洗い出す前に確認しておきたい。Active Assistの位置づけとして正しいものはどれか。',
   NULL::text,
   '["使用状況を分析し、アイドル状態のリソースの削除やサイズ変更などをAIが自動で推奨事項として提示する仕組みであり、まず確認すべき起点になる。","Active Assistは推奨事項を提示するだけでなく、承認なしに本番リソースを自動で変更・削除する仕組みである。","Active Assistはセキュリティ関連の推奨事項のみを扱い、コストやパフォーマンスの推奨は別のツールで確認する必要がある。","Active Assistの推奨事項は導入初期のみ生成され、運用が定常化した後は新しい推奨が出てこない。"]',
   0,
   '[0]',
   'single',
   '{"asked":"Active Assistの推奨事項（インサイト）の役割と適用範囲を理解しているか。","why_asked":"試験ガイドはパフォーマンス情報の収集の項目にActive Assistのインサイトと推奨事項を明記している。試験はAIによる推奨を『自動実行される』と過信する誤答と、『対象範囲が狭い/一時的』と過小評価する誤答の両方を置き、『継続的に提示される起点であり実行は人が判断する』という位置づけを測る。","kid":"使われていないリソースなどをAIが継続的に見つけて教えてくれる。実行するかは人が決める。","terms":[["Active Assist","使用状況を分析し、コスト・パフォーマンス・セキュリティなどの推奨事項を提示するGoogle Cloudの機能群。"],["推奨事項(レコメンダー)","個々の分析結果として提示される具体的な改善提案。"]],"think":"全リソースを人力で洗い出すのは非効率。AIが継続的に使用状況を分析し推奨を提示し続けるので、まずそこを確認してから人が実行判断をする、という順序で考える。","vs":"『自動実行される』と『対象や期間が限定的』のどちらも誤り。推奨は継続的に出続け、実行は人の判断に委ねられている。","opt":["正解。使用状況の分析結果を推奨事項として提示し続ける起点であり、実行するかは人が判断する。","Active Assistの推奨事項は提示のみで、承認なしに本番リソースを自動変更・削除する仕組みではない。","Active Assistはセキュリティに限らず、コストやパフォーマンスなど複数分野の推奨事項を扱う。","Active Assistの推奨事項は使用状況の変化に応じて継続的に生成され、導入初期だけに限られない。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'gcp-pcde'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
